{
  "segment_function": "To define the concept of work in contrast to labor, introduce the human artifice and its durability, and distinguish use objects from consumer goods.",
  "claims": [
    {
      "claim": "Homo faber makes and works upon things to fabricate the human artifice, distinguishing work from the labor of the animal laborans.",
      "claim_type": "author_position",
      "supporting_excerpt": "The work of our hands, as distinguished from the labor of our bodies— homo faber who makes and literally “works upon” as distinguished from the animal laborans which labors and “mixes with”—fabricates the sheer unending variety of things whose sum total constitutes the human artifice.",
      "support_kind": "direct",
      "qualifications": [
        "Mostly but not exclusively objects for use"
      ],
      "confidence": 1.0
    },
    {
      "claim": "The durability of the things of the world provides them with objectivity and relative independence from their makers, serving to stabilize human life and identity against mere biological flux.",
      "claim_type": "author_position",
      "supporting_excerpt": "It is this durability which gives the things of the world their relative independence from men who produced and use them, their “objectivity” which makes them withstand, “stand against” and endure, at least for a time, the voracious needs and wants of their living makers and users.",
      "support_kind": "direct",
      "qualifications": [
        "Durability is not absolute and is worn out by usage"
      ],
      "confidence": 1.0
    }
  ],
  "definitions": [
    {
      "term": "Homo faber",
      "definition": "The maker who works upon materials to fabricate the variety of things that constitute the human artifice."
    },
    {
      "term": "Human artifice",
      "definition": "The sum total of things produced by human work, possessing durability, stability, and objectivity to house mortal men."
    }
  ],
  "distinctions": [
    {
      "item_a": "Work",
      "item_b": "Labor",
      "distinction": "Work is performed by homo faber who makes and works upon things, whereas labor is performed by the animal laborans which labors and mixes with things."
    },
    {
      "item_a": "Use",
      "item_b": "Consumption",
      "distinction": "Destruction is incidental to use, whereas destruction is inherent in consumption."
    }
  ]
}

